/**
 * Sensitivity (27-grid) — STANDALONE variant: validates the frozen artifact
 * rather than re-running.
 *
 * The host-repo test re-executes runSensitivityAsync, which needs the full
 * agent framework (the full-rules arm runs through CognitiveAgent). This
 * standalone repo carries the frozen report in
 * results/outcome-gm/sensitivity/envelope-sensitivity.json — regenerated by
 * the host whenever sensitivity.ts changes — and pins its headline numbers.
 */

import { describe, it, expect } from 'vitest';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const REPORT = join(fileURLToPath(new URL('..', import.meta.url)), 'results', 'outcome-gm', 'sensitivity', 'envelope-sensitivity.json');

interface SensitivityReport {
  version: string;
  grid: unknown[];
  arms: Array<{ armId: string; passPositiveByGrid: Record<string, number> }>;
  greedyMinusNoOpByGrid: Record<string, number>;
  admissionChurnRateByGrid: Record<string, number>;
  rankStableAllGrids: boolean;
}

describe('envelope sensitivity (frozen 27-grid artifact)', () => {
  const report = existsSync(REPORT)
    ? (JSON.parse(readFileSync(REPORT, 'utf8')) as SensitivityReport)
    : null;

  it('artifact exists', () => {
    expect(report, `missing ${REPORT}`).not.toBeNull();
  });

  it('27 grid points, all five arms present', () => {
    expect(report!.grid).toHaveLength(27);
    expect(report!.arms.map(a => a.armId).sort()).toEqual([
      'centralized-llm', 'distributed-llm', 'full-rules', 'no-op', 'perfect-info-greedy',
    ]);
  });

  it('pinned: rank-stable, Δ(greedy−no-op) ∈ [0.9104, 1], agent arms at floor', () => {
    expect(report!.rankStableAllGrids).toBe(true);
    const deltas = Object.values(report!.greedyMinusNoOpByGrid);
    expect(Math.min(...deltas)).toBeGreaterThanOrEqual(0.9104);
    expect(Math.max(...deltas)).toBeLessThanOrEqual(1.0);
    for (const arm of report!.arms) {
      if (arm.armId === 'perfect-info-greedy' || arm.armId === 'no-op') continue;
      const maxRate = Math.max(...Object.values(arm.passPositiveByGrid));
      expect(maxRate).toBeLessThanOrEqual(0.05);
    }
  });

  it('pinned: admission churn is a pure deadline effect, worst 8.96% (6/67)', () => {
    const rates = Object.entries(report!.admissionChurnRateByGrid);
    expect(Math.max(...rates.map(([, v]) => v))).toBeCloseTo(0.0896, 3);
    for (const [gridKey, rate] of rates) {
      if (rate > 0) expect(gridKey.startsWith('0.8-'), gridKey).toBe(true);
      else expect(rate).toBe(0);
    }
  });
});
